public class Benchmark {
    static long fibonacci(int number) { return number < 2 ? number : fibonacci(number - 1) + fibonacci(number - 2); }
    static long fibonacciIterative(int number) { long previous = 0, current = 1; for (int index = 0; index < number; index++) { long next = previous + current; previous = current; current = next; } return previous; }
    static int countPrimes(int limit) { boolean[] prime = new boolean[limit + 1]; java.util.Arrays.fill(prime, true); prime[0] = prime[1] = false; for (int number = 2; number * number <= limit; number++) if (prime[number]) for (int multiple = number * number; multiple <= limit; multiple += number) prime[multiple] = false; int count = 0; for (boolean value : prime) if (value) count++; return count; }
    public static void main(String[] args) { int fibonacciInput = args.length > 0 ? Integer.parseInt(args[0]) : 37; int primeLimit = args.length > 1 ? Integer.parseInt(args[1]) : 2000000; int numericIterations = args.length > 2 ? Integer.parseInt(args[2]) : 100000; long start = System.nanoTime(); long fr = fibonacci(fibonacciInput); double ft = (System.nanoTime() - start) / 1e9; start = System.nanoTime(); int pr = countPrimes(primeLimit); double pt = (System.nanoTime() - start) / 1e9; start = System.nanoTime(); long numericResult = 0; for (int iteration = 0; iteration < numericIterations; iteration++) numericResult += fibonacciIterative(fibonacciInput); double nt = (System.nanoTime() - start) / 1e9; if (numericResult < 0) throw new IllegalStateException(); System.out.printf("%.6f,%.6f,%.6f,%d,%d,%d%n", ft, pt, nt, fr, pr, numericResult); }
}
